CREATE TABLE vehicles (
    id SERIAL PRIMARY KEY,
    vin VARCHAR(17) NOT NULL,
    manufacturer VARCHAR(50)
);

CREATE TABLE electric_cars (
    battery_capacity_kwh NUMERIC(5, 2)
) INHERITS (vehicles);

-- Querying vehicles returns rows from electric_cars too!
SELECT * FROM vehicles;

-- Use ONLY to exclude inherited children
SELECT * FROM ONLY vehicles;

CREATE TABLE vehicles (
    id   bigserial PRIMARY KEY,
    vin  text NOT NULL
);

CREATE TABLE cars (
    doors int
) INHERITS (vehicles);

CREATE TABLE trucks (
    payload_kg numeric
) INHERITS (vehicles);

-- Includes rows from cars and trucks
SELECT * FROM vehicles;

-- Excludes children: only rows physically in vehicles
SELECT * FROM ONLY vehicles;
